import{_ as s}from"./chunks/projects-sidebar-manager.1CSA31F-.js";import{_ as a,a as i,b as r,c as n,d as t}from"./chunks/web-panel-016-177.BgfcPA07.js";import{_ as l,o,c as u,a3 as d}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"Sidebar Manager","description":"Dossiers, couleurs, opacité et liens dans la barre latérale Home Assistant. Version 0.1.9, DE/EN/FR.","frontmatter":{"title":"Sidebar Manager","description":"Dossiers, couleurs, opacité et liens dans la barre latérale Home Assistant. Version 0.1.9, DE/EN/FR."},"headers":[],"relativePath":"fr/projects/sidebar-manager/index.md","filePath":"fr/projects/sidebar-manager/index.md","lastUpdated":1794053025000}'),p={name:"fr/projects/sidebar-manager/index.md"};function c(m,e,g,h,b,f){return o(),u("div",null,[...e[0]||(e[0]=[d('<h1 id="sidebar-manager" tabindex="-1">Sidebar Manager <a class="header-anchor" href="#sidebar-manager" aria-label="Permalink to &quot;Sidebar Manager&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">HA 2026.11 : aperçu des couleurs corrigé</p><p>La version <strong>0.1.9</strong> corrige les couleurs du texte/des icônes dans le dialogue natif, y compris celles des groupes. Vérifié sur .177 (port 80), Core 2026.11.0 / frontend 20261028.4 : couleurs, opacité, annulation, enregistrement, réinitialisation au thème et rechargement complet. Les 72 tests automatisés réussissent. Groupe/lien de test supprimés ; disposition exportée identique à la sauvegarde initiale. Paramètres existants et « Test für APP » conservés.</p></div><p><a href="/fr/collection/ha-2026-11-compatibility">Périmètre, résultats et problèmes ouverts</a>.</p><img src="'+s+`" width="80" height="80" alt="Sidebar Manager"><p><strong>0.1.9 · Home Assistant ≥ 2026.10.3 · DE / EN / FR · MIT</strong></p><p>Dossiers, couleurs, opacité et liens personnalisés dans « Modifier la barre latérale ». Triez dossiers et entrées principales avec les poignées natives. Aucun fichier système HA n&#39;est remplacé.</p><p><a href="https://github.com/rockbaer2007/ha-sidebar-manager" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/ha-sidebar-manager/releases/tag/v0.1.9" target="_blank" rel="noreferrer">Release 0.1.9</a> · <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-manager&amp;category=plugin" target="_blank" rel="noreferrer">HACS</a></p><h2 id="nouveautes-de-0-1-8-liens-dans-l-editeur-de-barre-laterale" tabindex="-1">Nouveautés de 0.1.8 : liens dans l’éditeur de barre latérale <a class="header-anchor" href="#nouveautes-de-0-1-8-liens-dans-l-editeur-de-barre-laterale" aria-label="Permalink to &quot;Nouveautés de 0.1.8 : liens dans l’éditeur de barre latérale&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">État des vérifications, 2 novembre 2026</p><p><strong>0.1.8 : vérification fonctionnelle réussie confirmée par l’utilisateur le 2 novembre 2026.</strong> Liens, couleurs, déplacement et libellés « Lien »/« Lien ext. » fonctionnent. La vérification syntaxique, la compilation et <strong>70 tests automatisés</strong> réussissent aussi. Les images existantes montrent les vérifications antérieures. Codex n’a pas effectué de test d’exécution HA indépendant supplémentaire pour cette version ; l’hôte et la version HA du test utilisateur n’ont pas été précisés séparément.</p></div><p>Les liens personnalisés internes et externes apparaissent aussi dans <strong>Modifier la barre latérale</strong>. Sans position enregistrée, ils apparaissent d’abord à la fin ; l’ordre existant est respecté. Les liens masqués restent disponibles pour modification.</p><ul><li><strong>Champ de couleur :</strong> même sélecteur de couleur et d’opacité que pour les entrées HA. « Couleur du thème » retire la couleur personnalisée. Les couleurs enregistrées sont appliquées dès la création des lignes de la barre latérale.</li><li><strong>Type de lien :</strong> le bouton des réglages affiche <strong>Lien</strong> pour une destination interne et <strong>Lien ext.</strong> pour une destination HTTP(S) externe, à la place du nom du dossier. Un clic ouvre les réglages du lien. Son dossier reste conservé et figure aussi dans l’infobulle.</li><li><strong>Poignée :</strong> triez les liens avec les autres entrées, y compris dans leur dossier. Le déplacement seul ne change pas le dossier attribué ; choisissez celui-ci dans les réglages du lien. Le tri au clavier reste disponible.</li><li><strong>Œil :</strong> masquez ou affichez un lien sans supprimer le lien ni ses réglages.</li><li><strong>Enregistrer/Annuler :</strong> appliquez ou abandonnez les changements de couleur, visibilité et ordre dans la fenêtre HA. Les réglages généraux des liens restent enregistrés dans le Manager.</li></ul><p>L’ordre et la visibilité des liens restent dans <code>ugso_sidebar_manager_v1</code>, les couleurs dans le relevé existant <code>ugso_sidebar_colors_v1</code>. Les identifiants des liens personnalisés ne sont jamais écrits dans l’ordre natif des panneaux HA. Réglages existants, modes d’ouverture et panneaux absents sont conservés.</p><p>Les vérifications locales couvrent le paquet JavaScript compilé avec un stockage HA simulé, les libellés DE/EN/FR, la couleur, l’enregistrement/annulation, le tri, le dossier attribué et la restauration après un échec d’enregistrement. L’utilisateur a confirmé la réussite de la vérification fonctionnelle le 2 novembre 2026 ; cette validation est documentée séparément des tests automatisés.</p><h2 id="hacs-marketplace" tabindex="-1">HACS / Marketplace <a class="header-anchor" href="#hacs-marketplace" aria-label="Permalink to &quot;HACS / Marketplace&quot;">​</a></h2><p>Plugin frontend, pas une application Supervisor ni une carte de tableau de bord. Ajoutez <code>https://github.com/rockbaer2007/ha-sidebar-manager</code> comme dépôt personnalisé HACS, catégorie <strong>Dashboard</strong> (<code>plugin</code>), puis téléchargez-le. La publication n&#39;implique pas l&#39;inclusion au catalogue standard. Le paquet utilise une structure compatible HACS pour Marketplace.</p><div class="tip custom-block"><p class="custom-block-title">Installation Marketplace confirmée</p><p>Le <strong>5 novembre 2026</strong>, l’utilisateur a confirmé la réussite de l’installation via <strong>Marketplace</strong>. Cette confirmation complète les vérifications documentées de Sidebar Manager 0.1.9. La version exacte de Marketplace n’a pas été précisée séparément ; cela ne constitue pas une validation de toutes les versions.</p></div><p>Créez d&#39;abord une sauvegarde complète HA. Fusionnez dans la section <code>frontend:</code> existante de <code>configuration.yaml</code>, en conservant thèmes et autres modules :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-manager/ha-sidebar-manager.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Désactivez les anciens modules Sidebar Colors et Sidebar Organizer ; chargez seulement Sidebar Manager. Validez, redémarrez HA et rechargez le navigateur. Une simple ressource de tableau de bord ne suffit pas pour toutes les pages HA.</p><h2 id="installation-manuelle" tabindex="-1">Installation manuelle <a class="header-anchor" href="#installation-manuelle" aria-label="Permalink to &quot;Installation manuelle&quot;">​</a></h2><p>Copiez <code>ha-sidebar-manager.js</code> de la release vers <code>/config/www/ha-sidebar-manager/ha-sidebar-manager.js</code>, puis utilisez <code>/local/ha-sidebar-manager/ha-sidebar-manager.js</code> comme URL de module. Ne chargez pas simultanément les copies HACS et manuelle. Le ZIP contient le bundle, les exemples de configuration, la licence et les instructions DE/EN/FR. Un ancien chemin local versionné comme <code>/local/ugso-sidebar-manager/0.1.7/ha-sidebar-manager.js</code> reste possible si le fichier correspondant existe. Conservez le chemin choisi lors des mises à jour et rechargez le navigateur.</p><h2 id="sites-affiches-a-droite-dans-ha" tabindex="-1">Sites affichés à droite dans HA <a class="header-anchor" href="#sites-affiches-a-droite-dans-ha" aria-label="Permalink to &quot;Sites affichés à droite dans HA&quot;">​</a></h2><p>Les liens ouvrant un nouvel onglet n&#39;exigent aucune configuration supplémentaire. Pour <strong>Afficher à droite (iframe)</strong>, fusionnez aussi dans <code>configuration.yaml</code> ou la liste <code>panel_custom</code> existante :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">panel_custom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ugso-sidebar-web</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    url_path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ugso-sidebar-web</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-manager/ha-sidebar-manager.js</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    embed_iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require_admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Pour une installation manuelle, utilisez <code>/local/ha-sidebar-manager/ha-sidebar-manager.js</code> comme <code>module_url</code>. Cette URL doit correspondre au module frontend. Validez et redémarrez HA. Sans <code>sidebar_title</code>, aucune entrée supplémentaire n&#39;est créée. Exemples dans le ZIP : <code>panel-custom.example.yaml</code> et <code>panel-custom.manual.example.yaml</code>.</p><p>Le site cible doit autoriser l&#39;intégration. CSP/X-Frame-Options, HTTPS-vers-HTTP ou sa propre authentification peuvent empêcher l&#39;affichage. L&#39;ouverture dans un nouvel onglet reste disponible. Aucun jeton HA n&#39;est transmis au site et les autorisations HA restent applicables.</p><h2 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h2><p>Maintenez l&#39;en-tête de la barre latérale. Couleurs, yeux et poignées restent dans la fenêtre HA ; « Gérer les groupes et les liens » ouvre le Manager. DE/EN/FR suit la langue HA, avec anglais par défaut.</p><ul><li>Couleur et opacité par entrée ; « Couleur du thème » retire la couleur personnalisée. Le damier représente la transparence.</li><li>Dossiers avec nom, icône MDI, couleur et état replié/déplié initial. Affectez les entrées et liens existants ; « Menu principal » permet de les ramener.</li><li>Déplacez les dossiers entre les entrées principales. Dossier et contenu bougent ensemble ; Alt+Haut/Bas permet le tri au clavier.</li><li>Les dossiers épinglés en bas apparaissent aussi en bas dans l&#39;éditeur. Les déplacer avant un bloc normal retire leur épinglage inférieur. Annuler conserve position et épinglage.</li><li>Séparateur <strong>0–4 px</strong>, 0 = désactivé. Visible uniquement lorsque le groupe est déplié, après son contenu, avec couleur/opacité de l&#39;icône et 1 px d&#39;espacement au-dessus et au-dessous.</li><li>Ajoutez Journaux, Automatisations et États avec un dossier au choix. Les liens correspondants sont réutilisés ; noms et icônes restent modifiables.</li><li>Liens internes personnalisés jaune clair dans les réglages, liens HTTP(S) externes bleu clair. Nouvel onglet ou iframe pour les liens externes. Les anciens gardent leur comportement précédent jusqu&#39;à modification. Couleurs personnalisées de la barre latérale conservées.</li><li>Enregistrer dans le Manager applique l&#39;organisation. Couleurs/ordre natif modifiés dans la fenêtre HA sous-jacente doivent y être enregistrés séparément. Annuler abandonne le brouillon concerné.</li></ul><p>Réglages, profil et notifications restent natifs. Masquer ou regrouper ne change pas les droits d&#39;accès.</p><h2 id="images-et-verification" tabindex="-1">Images et vérification <a class="header-anchor" href="#images-et-verification" aria-label="Permalink to &quot;Images et vérification&quot;">​</a></h2><p><img src="`+a+'" alt="Sélecteur de couleur"></p><p><img src="'+i+'" alt="Options des liens"></p><p><img src="'+r+'" alt="Position du dossier en 0.1.7"></p><p><img src="'+n+'" alt="Dossier replié sans séparateur"></p><p><img src="'+t+'" alt="Site affiché à droite dans HA"></p><p>0.1.7 vérifiée sur HA <strong>2026.10.4</strong>, port 80 : enregistrement/annulation, déplacement d&#39;un dossier de test épinglé, rechargement, affectation et séparateurs uniquement dépliés. Les tests antérieurs couvrent couleurs, opacité, liens, iframe/nouvel onglet et export/import. Données et tableau de test conservés, objets temporaires supprimés. <strong>60 tests automatisés réussis.</strong> Les images couleur/liens de 0.1.6 montrent des fonctions toujours valides. <a href="https://github.com/rockbaer2007/ha-sidebar-manager/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Historique des tests</a>.</p><p>2026.10.3 est le minimum prévu, sans installation distincte testée en direct. Aucune compatibilité générale revendiquée avec tous les sites ou versions Marketplace.</p><h2 id="conserver-les-reglages-et-migrer" tabindex="-1">Conserver les réglages et migrer <a class="header-anchor" href="#conserver-les-reglages-et-migrer" aria-label="Permalink to &quot;Conserver les réglages et migrer&quot;">​</a></h2><ol><li>Sauvegardez HA complètement et exportez les réglages Organizer ainsi que les sauvegardes Manager/couleurs disponibles.</li><li>Désactivez les anciens modules sans supprimer leurs fichiers ni réglages. Installez une seule copie du Manager.</li><li>Couleurs Sidebar Colors conservées dans <code>ugso_sidebar_colors_v1</code>, organisation Manager dans <code>ugso_sidebar_manager_v1</code>, synchronisées sur le serveur par utilisateur HA.</li><li><strong>Aucun import automatique YAML/présentation Organizer.</strong> Conservez son export et recréez manuellement les groupes/liens souhaités.</li></ol><p>Les panneaux absents restent enregistrés. Une erreur de lecture ou un format inconnu n&#39;écrit pas de valeurs par défaut. L&#39;organisation précédente est sauvegardée dans le navigateur avant écriture ; un stockage bloqué empêche l&#39;enregistrement. Conflits vérifiés avant écriture, confirmations incertaines contrôlées par relecture. Une courte course entre écritures simultanées reste possible sans comparaison atomique serveur.</p><p>Export/import JSON : dossiers, liens, noms, icônes, visibilité, épinglage, ordre et séparateurs ; aucun identifiant d&#39;accès ni réglage HA natif. Les couleurs des entrées gardent leur sauvegarde distincte. Réinitialiser change seulement le brouillon jusqu&#39;à son enregistrement. Pour revenir, restaurez l&#39;ancien module, redémarrez HA et rechargez le navigateur sans supprimer les données utilisateur.</p><h2 id="developpement-et-limites" tabindex="-1">Développement et limites <a class="header-anchor" href="#developpement-et-limites" aria-label="Permalink to &quot;Développement et limites&quot;">​</a></h2><p>Node ≥22 : <code>npm ci</code>, <code>npm run check</code>, <code>npm run build</code>, <code>npm test</code>. Les tags génèrent JS et ZIP automatiquement. Les interfaces internes HA peuvent changer. Pas de présentations par appareil, CSS/modèles libres, migration automatique Organizer ou réglages d&#39;en-tête/largeur.</p><p>Implémentation UGSo originale basée sur Sidebar Colors. <a href="https://github.com/ngocjohn/sidebar-organizer" target="_blank" rel="noreferrer">Sidebar Organizer de Viet Ngoc</a> sert de référence fonctionnelle ; aucun code Organizer intégré. Licence MIT dans le dépôt.</p>',45)])])}const A=l(p,[["render",c]]);export{_ as __pageData,A as default};
